package kr.blackwiki.smp;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.bukkit.World;
import org.bukkit.configuration.file.YamlConfiguration;
import java.nio.file.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class Update33Test {
 @TempDir Path dir;
 @Test void foodBundlePricesAndQuantitiesMatchRequest(){String[] ids={"food_bread_10","food_apple_10","food_pork_10","food_steak_10","food_golden_apple_5","food_enchanted_apple_5"};long[] prices={100,70,120,120,500,5000};int[] units={10,10,10,10,5,5};for(int i=0;i<ids.length;i++){var p=ShopCatalogue.find(ids[i]);assertEquals(prices[i],p.total(false,1));assertEquals(units[i],p.units());assertEquals(ShopCatalogue.Category.FOOD,p.category());assertThrows(IllegalArgumentException.class,()->p.total(true,1));}}
 @Test void foodQuantityMeansBundlesAndDoesNotChargePerIndividualItem(){var p=ShopCatalogue.find("food_bread_10");assertEquals(300,p.total(false,3));assertEquals(30,FoodBundles.delivered(p.id(),3));assertEquals("3묶음 (30개)",p.quantityLabel(3));assertEquals(640,FoodBundles.delivered(p.id(),64));}
 @Test void enchantedAppleBundleIsFiveNotOneOrTen(){var p=ShopCatalogue.find("food_enchanted_apple_5");assertEquals(10,FoodBundles.delivered(p.id(),2));assertEquals(10000,p.total(false,2));}
 @Test void invalidBundleQuantityCannotGenerateFreeFood(){for(int n:new int[]{-1,0,65,Integer.MAX_VALUE})assertThrows(IllegalArgumentException.class,()->FoodBundles.delivered("food_bread_10",n));}
 @Test void productIdsStayUniqueAndSpecialWeaponsKeepTheirPrices(){assertEquals(56,ShopCatalogue.ALL.size());assertEquals(56,new HashSet<>(ShopCatalogue.ALL.stream().map(ShopCatalogue.Product::id).toList()).size());assertEquals(250000,ShopCatalogue.find("double_barrel_shotgun").buy());assertEquals(6,FoodBundles.ALL.size());}
 @Test void firstTipArrivesAtExactlyFiveMinutes(){var c=new TipCycle(0,new Random(3));assertEquals(-1,c.poll(TipCycle.INTERVAL-1));assertTrue(c.poll(TipCycle.INTERVAL)>=0);assertEquals(-1,c.poll(TipCycle.INTERVAL));}
 @Test void sevenTipsFormRandomBagsWithoutAdjacentRepeats(){var c=new TipCycle(0,new Random(9));int previous=-1;for(int bag=0;bag<30;bag++){Set<Integer> seen=new HashSet<>();for(int i=0;i<21;i++){int n=c.poll((bag*21L+i+1)*TipCycle.INTERVAL);assertTrue(n>=0&&n<21);assertNotEquals(previous,n);assertTrue(seen.add(n));previous=n;}assertEquals(21,seen.size());}}
 @Test void lagDoesNotFloodChatWithCatchupMessages(){var c=new TipCycle(0,new Random(1));long now=1000*TipCycle.INTERVAL;assertTrue(c.poll(now)>=0);assertEquals(-1,c.poll(now));assertEquals(-1,c.poll(now+TipCycle.INTERVAL-1));assertTrue(c.poll(now+TipCycle.INTERVAL)>=0);}
 @Test void tipSetContainsSevenKoreanGuides(){assertEquals(21,TipService.MESSAGES.size());assertTrue(TipService.MESSAGES.stream().allMatch(s->!s.isBlank()&&s.length()<240));}
 @Test void antiXrayUsesPerDimensionOresInsteadOfNetherOresEverywhere(){assertTrue(AntiXrayProfile.hidden(World.Environment.NETHER).contains("ancient_debris"));assertFalse(AntiXrayProfile.hidden(World.Environment.NORMAL).contains("ancient_debris"));assertTrue(AntiXrayProfile.hidden(World.Environment.NORMAL).contains("deepslate_diamond_ore"));assertTrue(AntiXrayProfile.hidden(World.Environment.NORMAL).contains("raw_iron_block"));}
 @Test void tileEntitiesAreNeverUsedAsFakeBlocks(){for(var e:World.Environment.values())for(String c:AntiXrayProfile.CONTAINERS)assertFalse(AntiXrayProfile.hidden(e).contains(c));assertTrue(AntiXrayProfile.replacements(World.Environment.NORMAL).contains("barrel"));assertTrue(AntiXrayProfile.replacements(World.Environment.NORMAL).contains("red_shulker_box"));}
 @Test void antiXrayProfilePreservesOtherSettingsAndDisablesBypass(){var y=new YamlConfiguration();y.set("unrelated.setting",73);AntiXrayProfile.apply(y,World.Environment.NORMAL,320);assertEquals(73,y.getInt("unrelated.setting"));assertTrue(y.getBoolean(AntiXrayProfile.ROOT+"enabled"));assertEquals(3,y.getInt(AntiXrayProfile.ROOT+"engine-mode"));assertFalse(y.getBoolean(AntiXrayProfile.ROOT+"use-permission"));assertTrue(AntiXrayProfile.matches(y,World.Environment.NORMAL,320));assertFalse(AntiXrayProfile.matches(y,World.Environment.NETHER,256));}
 @Test void antiXrayCoversFullWorldHeightAlignedToSections(){assertEquals(320,AntiXrayProfile.ceiling(320));assertEquals(256,AntiXrayProfile.ceiling(256));assertEquals(336,AntiXrayProfile.ceiling(321));assertThrows(IllegalArgumentException.class,()->AntiXrayProfile.ceiling(0));}
 @Test void graveIndexRevisionTracksDurablyPublishedChanges()throws Exception{var l=new GraveLedger(dir.resolve("g.yml"));var g=new GraveLedger.Grave(UUID.randomUUID(),UUID.randomUUID(),100,"world",UUID.randomUUID(),1,80,1,false,GraveLedger.State.OPEN,List.of("item"),null,null,-1);assertEquals(0,l.revision());l.put(g);assertEquals(1,l.revision());l.put(g.physical(true));assertEquals(2,l.revision());assertTrue(new GraveLedger(dir.resolve("g.yml")).get(g.id()).virtual());}
 @Test void upgradeFrom32PreservesCustomSettingsAndAddsTipsAndAntiXray()throws Exception{Path p=dir.resolve("config.yml");String old="config-version: 32\nqueue:\n  player-slots: 71\nhelp-tips:\n  enabled: false\n";Files.writeString(p,old);var r=UpgradeService.migrate(p,Files.readString(Path.of("src/main/resources/config.yml")));var y=YamlConfiguration.loadConfiguration(p.toFile());assertEquals(32,r.from());assertEquals(35,r.to());assertEquals(71,y.getInt("queue.player-slots"));assertFalse(y.getBoolean("help-tips.enabled"));assertTrue(y.getBoolean("anti-xray.auto-configure"));assertEquals(old,Files.readString(dir.resolve("config.yml.before-3.5.bak")));assertFalse(UpgradeService.migrate(p,Files.readString(Path.of("src/main/resources/config.yml"))).changed());}
 @Test void tipsAndLegacyCommandsRemainRegistered(){var y=YamlConfiguration.loadConfiguration(Path.of("src/main/resources/plugin.yml").toFile());assertEquals("3.7",y.getString("version"));assertTrue(y.getStringList("commands.smptips.aliases").contains("도움말"));assertTrue(y.getStringList("commands.smpcommands.aliases").contains("명령어"));assertTrue(y.getStringList("commands.smpcoingive.aliases").contains("코인지급"));}
}
